using System.Globalization;
using System.Text.Json;
using Microsoft.Data.Sqlite;
using PFA_FVG_Scanner.Domain.OrderFlow;

namespace PFA_FVG_Scanner.Data;

public sealed class OrderFlowRepository
{
    private readonly PfaDatabase _database;public OrderFlowRepository(PfaDatabase database)=>_database=database;
    public async Task SaveEventsAsync(IReadOnlyList<CanonicalOrderFlowEvent> events,CancellationToken token=default)
    {
        await using var connection=_database.CreateConnection();await connection.OpenAsync(token);await using var transaction=(SqliteTransaction)await connection.BeginTransactionAsync(token);
        foreach(var item in events)
        {
            await using(var check=connection.CreateCommand()){check.Transaction=transaction;check.CommandText="SELECT ContentHash FROM OrderFlowEvents WHERE Provider=$provider AND ProviderEventId=$event";Add(check,"$provider",item.Provider);Add(check,"$event",item.ProviderEventId);var scalar=await check.ExecuteScalarAsync(token);if(scalar is not null&&Convert.ToString(scalar,CultureInfo.InvariantCulture)!=item.ContentHash)throw new InvalidOperationException($"Provider event identity conflict for {item.Provider}/{item.ProviderEventId}.");if(scalar is not null)continue;}
            await using var command=connection.CreateCommand();command.Transaction=transaction;command.CommandText="""
                INSERT INTO OrderFlowEvents(CanonicalEventId,Provider,ProviderEventId,InstrumentId,ContractId,ProviderSymbol,
                    EventKind,EventTimeUtc,KnownAtUtc,ProviderSequence,Operation,SupersedesCanonicalEventId,QualityFlags,ContentHash,EventJson)
                VALUES($id,$provider,$event,$instrument,$contract,$symbol,$kind,$eventTime,$knownAt,$sequence,$operation,$supersedes,$quality,$hash,$json)
                """;Add(command,"$id",item.CanonicalEventId);Add(command,"$provider",item.Provider);Add(command,"$event",item.ProviderEventId);Add(command,"$instrument",item.InstrumentId);Add(command,"$contract",item.ContractId);Add(command,"$symbol",item.ProviderSymbol);Add(command,"$kind",item.Kind.ToString());Add(command,"$eventTime",item.EventTimeUtc.ToString("O"));Add(command,"$knownAt",item.KnownAtUtc.ToString("O"));Add(command,"$sequence",item.ProviderSequence);Add(command,"$operation",item.Operation.ToString());Add(command,"$supersedes",item.SupersedesCanonicalEventId);Add(command,"$quality",(int)item.QualityFlags);Add(command,"$hash",item.ContentHash);Add(command,"$json",JsonSerializer.Serialize(item));await command.ExecuteNonQueryAsync(token);
        }
        await transaction.CommitAsync(token);
    }
    public async Task SaveClassificationsAsync(IReadOnlyList<ClassifiedTrade> trades,CancellationToken token=default)
    {await using var connection=_database.CreateConnection();await connection.OpenAsync(token);await using var transaction=(SqliteTransaction)await connection.BeginTransactionAsync(token);foreach(var item in trades){var json=JsonSerializer.Serialize(item);await using(var check=connection.CreateCommand()){check.Transaction=transaction;check.CommandText="SELECT TradeJson FROM OrderFlowClassifiedTrades WHERE CanonicalEventId=$id AND ClassifierVersion=$version AND DataRevision=$revision";Add(check,"$id",item.CanonicalEventId);Add(check,"$version",item.ClassifierVersion);Add(check,"$revision",item.DataRevision);var scalar=await check.ExecuteScalarAsync(token);if(scalar is not null&&Convert.ToString(scalar,CultureInfo.InvariantCulture)!=json)throw new InvalidOperationException("Order-flow classifications are immutable within a data revision.");if(scalar is not null)continue;}await using var command=connection.CreateCommand();command.Transaction=transaction;command.CommandText="""
        INSERT INTO OrderFlowClassifiedTrades(CanonicalEventId,ClassifierVersion,DataRevision,EventTimeUtc,KnownAtUtc,Side,TradeJson)
        VALUES($id,$version,$revision,$eventTime,$knownAt,$side,$json)
        """;Add(command,"$id",item.CanonicalEventId);Add(command,"$version",item.ClassifierVersion);Add(command,"$revision",item.DataRevision);Add(command,"$eventTime",item.EventTimeUtc.ToString("O"));Add(command,"$knownAt",item.KnownAtUtc.ToString("O"));Add(command,"$side",item.Side.ToString());Add(command,"$json",json);await command.ExecuteNonQueryAsync(token);}await transaction.CommitAsync(token);}
    public async Task SaveSnapshotAsync(OrderFlowFeatureSnapshot snapshot,CancellationToken token=default)
    {await using var connection=_database.CreateConnection();await connection.OpenAsync(token);await using(var check=connection.CreateCommand()){check.CommandText="SELECT ContentHash FROM OrderFlowFeatureSnapshots WHERE SnapshotId=$id";Add(check,"$id",snapshot.SnapshotId);var scalar=await check.ExecuteScalarAsync(token);if(scalar is not null&&Convert.ToString(scalar,CultureInfo.InvariantCulture)!=snapshot.ContentHash)throw new InvalidOperationException("Order-flow snapshots are immutable.");if(scalar is not null)return;}await using var command=connection.CreateCommand();command.CommandText="""
        INSERT INTO OrderFlowFeatureSnapshots(SnapshotId,InstrumentId,ContractId,WindowStartUtc,WindowEndUtc,KnownAtUtc,TradingSessionId,FeatureSetVersion,DataRevision,ContentHash,SnapshotJson)
        VALUES($id,$instrument,$contract,$start,$end,$known,$session,$version,$revision,$hash,$json)
        """;Add(command,"$id",snapshot.SnapshotId);Add(command,"$instrument",snapshot.InstrumentId);Add(command,"$contract",snapshot.ContractId);Add(command,"$start",snapshot.WindowStartUtc.ToString("O"));Add(command,"$end",snapshot.WindowEndUtc.ToString("O"));Add(command,"$known",snapshot.KnownAtUtc.ToString("O"));Add(command,"$session",snapshot.TradingSessionId);Add(command,"$version",snapshot.FeatureSetVersion);Add(command,"$revision",snapshot.DataRevision);Add(command,"$hash",snapshot.ContentHash);Add(command,"$json",JsonSerializer.Serialize(snapshot));await command.ExecuteNonQueryAsync(token);}
    public async Task<IReadOnlyList<CanonicalOrderFlowEvent>> GetEventsAsync(string instrumentId,DateTime startUtc,DateTime endUtc,DateTime asOfUtc,CancellationToken token=default)
    {var list=new List<CanonicalOrderFlowEvent>();await using var connection=_database.CreateConnection();await connection.OpenAsync(token);await using var command=connection.CreateCommand();command.CommandText="SELECT EventJson FROM OrderFlowEvents WHERE InstrumentId=$instrument AND EventTimeUtc>=$start AND EventTimeUtc<$end AND KnownAtUtc<=$known ORDER BY KnownAtUtc,COALESCE(ProviderSequence,9223372036854775807),CanonicalEventId";Add(command,"$instrument",instrumentId.Trim().ToUpperInvariant());Add(command,"$start",OrderFlowCanonicalizer.Utc(startUtc).ToString("O"));Add(command,"$end",OrderFlowCanonicalizer.Utc(endUtc).ToString("O"));Add(command,"$known",OrderFlowCanonicalizer.Utc(asOfUtc).ToString("O"));await using var reader=await command.ExecuteReaderAsync(token);while(await reader.ReadAsync(token))list.Add(JsonSerializer.Deserialize<CanonicalOrderFlowEvent>(reader.GetString(0))!);return list;}
    public async Task<IReadOnlyList<CanonicalOrderFlowEvent>> FindProviderEventsAsync(IReadOnlyList<(string Provider,string ProviderEventId)> identities,CancellationToken token=default)
    {var output=new List<CanonicalOrderFlowEvent>();await using var connection=_database.CreateConnection();await connection.OpenAsync(token);foreach(var identity in identities.Distinct()){await using var command=connection.CreateCommand();command.CommandText="SELECT EventJson FROM OrderFlowEvents WHERE Provider=$provider AND ProviderEventId=$event";Add(command,"$provider",identity.Provider);Add(command,"$event",identity.ProviderEventId);var scalar=await command.ExecuteScalarAsync(token);if(scalar is not null)output.Add(JsonSerializer.Deserialize<CanonicalOrderFlowEvent>(Convert.ToString(scalar,CultureInfo.InvariantCulture)!)!);}return output;}
    public async Task<OrderFlowFeatureSnapshot?> FindSnapshotAsync(string snapshotId,CancellationToken token=default)
    {await using var connection=_database.CreateConnection();await connection.OpenAsync(token);await using var command=connection.CreateCommand();command.CommandText="SELECT SnapshotJson FROM OrderFlowFeatureSnapshots WHERE SnapshotId=$id";Add(command,"$id",snapshotId);var scalar=await command.ExecuteScalarAsync(token);return scalar is null?null:JsonSerializer.Deserialize<OrderFlowFeatureSnapshot>(Convert.ToString(scalar,CultureInfo.InvariantCulture)!);}
    private static void Add(SqliteCommand command,string name,object? value)=>command.Parameters.AddWithValue(name,value??DBNull.Value);
}
